package com.example.scope;

import org.springframework.beans.factory.config.Scope;
import org.springframework.lang.NonNull;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ThreadLocalScope implements Scope {

    private final ThreadLocal<Map<String, Object>> threadLocalScope = 
        ThreadLocal.withInitial(ConcurrentHashMap::new);

    private final ThreadLocal<Map<String, Runnable>> destructionCallbacks = 
        ThreadLocal.withInitial(ConcurrentHashMap::new);

    @Override
    @NonNull
    public Object get(@NonNull String name, @NonNull java.util.function.ObjectFactory<?> objectFactory) {
        Map<String, Object> scope = threadLocalScope.get();
        return scope.computeIfAbsent(name, k -> objectFactory.getObject());
    }

    @Override
    public Object remove(@NonNull String name) {
        Map<String, Runnable> callbacks = destructionCallbacks.get();
        if (callbacks.containsKey(name)) {
            callbacks.get(name).run();
            callbacks.remove(name);
        }
        return threadLocalScope.get().remove(name);
    }

    @Override
    public void registerDestructionCallback(@NonNull String name, @NonNull Runnable callback) {
        destructionCallbacks.get().put(name, callback);
    }

    @Override
    public Object resolveContextualObject(@NonNull String key) {
        return null;
    }

    @Override
    public String getConversationId() {
        return Thread.currentThread().getId() + "";
    }
}
